ALTER TABLE public.dashboard_access DROP CONSTRAINT valid_dashboard_permissions;
ALTER TABLE public.dashboard_access ADD CONSTRAINT valid_dashboard_permissions CHECK (permissions <@ ARRAY['products','prices','content','settings','messages','media','customers','serials','seo']::text[]);
CREATE OR REPLACE FUNCTION public.set_dashboard_access(_user_id uuid,_admin boolean,_permissions text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(762301); IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _permissions IS NULL OR array_position(_permissions,NULL) IS NOT NULL OR NOT (_permissions <@ ARRAY['products','prices','content','settings','messages','media','customers','serials','seo']::text[]) THEN RAISE EXCEPTION 'Invalid permissions'; END IF; IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=_user_id) THEN RAISE EXCEPTION 'Account not found'; END IF; IF NOT _admin AND _user_id=auth.uid() THEN RAISE EXCEPTION 'Cannot demote yourself'; END IF; IF NOT _admin AND public.has_role(_user_id,'admin') AND (SELECT count(*) FROM public.user_roles WHERE role='admin')<=1 THEN RAISE EXCEPTION 'Keep one administrator'; END IF; IF _admin THEN INSERT INTO public.user_roles(user_id,role) VALUES(_user_id,'admin') ON CONFLICT(user_id,role) DO NOTHING; ELSE DELETE FROM public.user_roles WHERE user_id=_user_id AND role='admin'; END IF; INSERT INTO public.dashboard_access(user_id,permissions) VALUES(_user_id,CASE WHEN _admin THEN '{}'::text[] ELSE _permissions END) ON CONFLICT(user_id) DO UPDATE SET permissions=excluded.permissions; END $$;
CREATE TABLE public.seo_pages(path text PRIMARY KEY CHECK(path ~ '^/[^?#\\]*$' AND path NOT LIKE '//%'), entity_type text NOT NULL DEFAULT 'page' CHECK(entity_type IN ('page','products','posts','services','product_groups','product_categories')), entity_id text, title_ar text NOT NULL DEFAULT '' CHECK(length(title_ar)<=200),title_en text NOT NULL DEFAULT '' CHECK(length(title_en)<=200),description_ar text NOT NULL DEFAULT '' CHECK(length(description_ar)<=500),description_en text NOT NULL DEFAULT '' CHECK(length(description_en)<=500),focus_keyword_ar text NOT NULL DEFAULT '',focus_keyword_en text NOT NULL DEFAULT '',secondary_keywords_ar text NOT NULL DEFAULT '',secondary_keywords_en text NOT NULL DEFAULT '',canonical_url text NOT NULL DEFAULT '' CHECK(canonical_url='' OR canonical_url ~ '^https://goldcenterstr\.com/[^?#]*$'),robots text NOT NULL DEFAULT 'index' CHECK(robots IN ('index','noindex')),og_title_ar text NOT NULL DEFAULT '',og_title_en text NOT NULL DEFAULT '',og_description_ar text NOT NULL DEFAULT '',og_description_en text NOT NULL DEFAULT '',image_url text NOT NULL DEFAULT '' CHECK(image_url='' OR image_url LIKE '/api/public/media/%' OR image_url ~ '^https://'),twitter_title_ar text NOT NULL DEFAULT '',twitter_title_en text NOT NULL DEFAULT '',twitter_description_ar text NOT NULL DEFAULT '',twitter_description_en text NOT NULL DEFAULT '',twitter_card text NOT NULL DEFAULT 'summary_large_image' CHECK(twitter_card IN ('summary','summary_large_image')),url_slug text NOT NULL DEFAULT '' CHECK(url_slug='' OR url_slug ~ '^[a-z0-9][a-z0-9-]{0,119}$'),updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(entity_type,url_slug));
ALTER TABLE public.seo_pages DROP CONSTRAINT seo_pages_entity_type_url_slug_key;
CREATE UNIQUE INDEX seo_entity_slug_unique ON public.seo_pages(entity_type,url_slug) WHERE url_slug<>'';
GRANT SELECT ON public.seo_pages TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.seo_pages TO authenticated; GRANT ALL ON public.seo_pages TO service_role;
ALTER TABLE public.seo_pages ENABLE ROW LEVEL SECURITY;
CREATE POLICY seo_pages_public ON public.seo_pages FOR SELECT TO anon,authenticated USING (path !~ '^/(admin|auth|account|cart|favorites|reset-password|set-password)(/|$)' AND (entity_type='page' OR (entity_type='products' AND EXISTS(SELECT 1 FROM public.products WHERE id::text=entity_id AND active)) OR (entity_type='posts' AND EXISTS(SELECT 1 FROM public.posts WHERE id::text=entity_id AND published)) OR entity_type IN ('services','product_groups','product_categories')));
CREATE POLICY seo_pages_staff ON public.seo_pages FOR ALL TO authenticated USING(public.has_dashboard_permission(auth.uid(),'seo')) WITH CHECK(public.has_dashboard_permission(auth.uid(),'seo'));
CREATE TABLE public.seo_keywords(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),keyword_ar text NOT NULL DEFAULT '',keyword_en text NOT NULL DEFAULT '',category text NOT NULL DEFAULT 'brand' CHECK(category IN ('gold_bars','silver_bars','gold_prices','buy_gold','bullion_trading','refining','wholesale','brand')),page_path text NOT NULL DEFAULT '/' REFERENCES public.seo_pages(path) ON DELETE CASCADE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.seo_keywords TO authenticated; GRANT ALL ON public.seo_keywords TO service_role; ALTER TABLE public.seo_keywords ENABLE ROW LEVEL SECURITY; CREATE POLICY seo_keywords_staff ON public.seo_keywords FOR ALL TO authenticated USING(public.has_dashboard_permission(auth.uid(),'seo')) WITH CHECK(public.has_dashboard_permission(auth.uid(),'seo'));
CREATE TABLE public.seo_images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),url text NOT NULL UNIQUE CHECK(url LIKE '/api/public/media/%' OR url ~ '^https://'),alt_ar text NOT NULL DEFAULT '',alt_en text NOT NULL DEFAULT '',decorative boolean NOT NULL DEFAULT false,optimized_url text NOT NULL DEFAULT '' CHECK(optimized_url='' OR optimized_url LIKE '/api/public/media/%'));
GRANT SELECT ON public.seo_images TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.seo_images TO authenticated; GRANT ALL ON public.seo_images TO service_role; ALTER TABLE public.seo_images ENABLE ROW LEVEL SECURITY; CREATE POLICY seo_images_public ON public.seo_images FOR SELECT TO anon,authenticated USING(true); CREATE POLICY seo_images_staff ON public.seo_images FOR ALL TO authenticated USING(public.has_dashboard_permission(auth.uid(),'seo')) WITH CHECK(public.has_dashboard_permission(auth.uid(),'seo'));
CREATE TABLE public.seo_redirects(source_path text PRIMARY KEY CHECK(source_path ~ '^/[^?#\\]*$' AND source_path NOT LIKE '//%'),target_path text NOT NULL CHECK(target_path ~ '^/[^?#\\]*$' AND target_path NOT LIKE '//%' AND target_path<>source_path),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.seo_redirects TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.seo_redirects TO authenticated; GRANT ALL ON public.seo_redirects TO service_role; ALTER TABLE public.seo_redirects ENABLE ROW LEVEL SECURITY; CREATE POLICY seo_redirects_public ON public.seo_redirects FOR SELECT TO anon,authenticated USING(active); CREATE POLICY seo_redirects_staff ON public.seo_redirects FOR ALL TO authenticated USING(public.has_dashboard_permission(auth.uid(),'seo')) WITH CHECK(public.has_dashboard_permission(auth.uid(),'seo'));
CREATE FUNCTION public.guard_seo_redirect() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE current_path text; hop integer; BEGIN PERFORM pg_advisory_xact_lock(762302); IF NEW.source_path ~ '^/(admin|auth|api|account|reset-password|set-password)(/|$)' OR NEW.target_path ~ '^/(admin|auth|api|account|reset-password|set-password)(/|$)' THEN RAISE EXCEPTION 'Private destinations not allowed'; END IF; IF NEW.active THEN current_path:=NEW.target_path; FOR hop IN 1..32 LOOP IF current_path=NEW.source_path THEN RAISE EXCEPTION 'Redirect cycle'; END IF; SELECT target_path INTO current_path FROM public.seo_redirects WHERE source_path=current_path AND active AND source_path<>NEW.source_path; IF NOT FOUND THEN RETURN NEW; END IF; END LOOP; RAISE EXCEPTION 'Redirect chain too long'; END IF; RETURN NEW; END $$;
CREATE TRIGGER seo_redirect_guard BEFORE INSERT OR UPDATE ON public.seo_redirects FOR EACH ROW EXECUTE FUNCTION public.guard_seo_redirect();
CREATE TABLE public.seo_config(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1),google_verification text NOT NULL DEFAULT '' CHECK(google_verification ~ '^[A-Za-z0-9_-]*$'),bing_verification text NOT NULL DEFAULT '' CHECK(bing_verification ~ '^[A-Za-z0-9_-]*$'),measurement_id text NOT NULL DEFAULT '' CHECK(measurement_id='' OR measurement_id ~ '^G-[A-Z0-9]+$'));
GRANT SELECT ON public.seo_config TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.seo_config TO authenticated; GRANT ALL ON public.seo_config TO service_role; ALTER TABLE public.seo_config ENABLE ROW LEVEL SECURITY; CREATE POLICY seo_config_public ON public.seo_config FOR SELECT TO anon,authenticated USING(true); CREATE POLICY seo_config_staff ON public.seo_config FOR ALL TO authenticated USING(public.has_dashboard_permission(auth.uid(),'seo')) WITH CHECK(public.has_dashboard_permission(auth.uid(),'seo'));
INSERT INTO public.seo_config(id) SELECT id FROM public.site_settings WHERE id=1;
CREATE TABLE public.seo_audits(path text PRIMARY KEY,score integer CHECK(score BETWEEN 0 AND 100),report jsonb NOT NULL DEFAULT '{}',checked_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.seo_audits TO authenticated; GRANT ALL ON public.seo_audits TO service_role; ALTER TABLE public.seo_audits ENABLE ROW LEVEL SECURITY; CREATE POLICY seo_audits_staff ON public.seo_audits FOR ALL TO authenticated USING(public.has_dashboard_permission(auth.uid(),'seo')) WITH CHECK(public.has_dashboard_permission(auth.uid(),'seo'));
CREATE TABLE public.seo_reports(provider text PRIMARY KEY CHECK(provider IN ('search_console','analytics')),selected_property text NOT NULL DEFAULT '',snapshot jsonb,refreshed_at timestamptz,error text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.seo_reports TO authenticated; GRANT ALL ON public.seo_reports TO service_role; ALTER TABLE public.seo_reports ENABLE ROW LEVEL SECURITY; CREATE POLICY seo_reports_staff ON public.seo_reports FOR ALL TO authenticated USING(public.has_dashboard_permission(auth.uid(),'seo')) WITH CHECK(public.has_dashboard_permission(auth.uid(),'seo'));
INSERT INTO public.seo_pages(path) SELECT unnest(ARRAY['/','/about','/products','/services','/contact','/blog','/news','/check-bar']) FROM public.site_settings WHERE id=1;
INSERT INTO public.seo_pages(path,entity_type,entity_id) SELECT '/products/'||id,'products',id::text FROM public.products;
INSERT INTO public.seo_pages(path,entity_type,entity_id) SELECT '/posts/'||slug,'posts',id::text FROM public.posts;
INSERT INTO public.seo_pages(path,entity_type,entity_id) SELECT '/services/'||id,'services',id::text FROM public.services;
INSERT INTO public.seo_pages(path,entity_type,entity_id) SELECT '/groups/'||id,'product_groups',id::text FROM public.product_groups;
INSERT INTO public.seo_pages(path,entity_type,entity_id) SELECT '/categories/'||id,'product_categories',id::text FROM public.product_categories;
CREATE FUNCTION public.register_seo_content() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE base text; BEGIN base:=CASE TG_TABLE_NAME WHEN 'product_groups' THEN '/groups/' WHEN 'product_categories' THEN '/categories/' ELSE '/'||TG_TABLE_NAME||'/' END; IF TG_OP='DELETE' THEN DELETE FROM public.seo_pages WHERE entity_type=TG_TABLE_NAME AND entity_id=OLD.id::text; RETURN OLD; END IF; INSERT INTO public.seo_pages(path,entity_type,entity_id) VALUES(base||CASE WHEN TG_TABLE_NAME='posts' THEN to_jsonb(NEW)->>'slug' ELSE NEW.id::text END,TG_TABLE_NAME,NEW.id::text) ON CONFLICT(path) DO UPDATE SET updated_at=now(); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.register_seo_content() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER product_seo_register AFTER INSERT OR UPDATE OR DELETE ON public.products FOR EACH ROW EXECUTE FUNCTION public.register_seo_content();
CREATE TRIGGER post_seo_register AFTER INSERT OR UPDATE OR DELETE ON public.posts FOR EACH ROW EXECUTE FUNCTION public.register_seo_content();
CREATE TRIGGER service_seo_register AFTER INSERT OR UPDATE OR DELETE ON public.services FOR EACH ROW EXECUTE FUNCTION public.register_seo_content();
CREATE TRIGGER group_seo_register AFTER INSERT OR UPDATE OR DELETE ON public.product_groups FOR EACH ROW EXECUTE FUNCTION public.register_seo_content();
CREATE TRIGGER category_seo_register AFTER INSERT OR UPDATE OR DELETE ON public.product_categories FOR EACH ROW EXECUTE FUNCTION public.register_seo_content();
CREATE FUNCTION public.seo_page_changed() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE base text; old_url text; new_url text; BEGIN NEW.updated_at:=now(); IF NEW.url_slug IS DISTINCT FROM OLD.url_slug AND NEW.entity_type<>'page' THEN base:=regexp_replace(NEW.path,'[^/]+$',''); old_url:=CASE WHEN OLD.url_slug='' THEN OLD.path ELSE base||OLD.url_slug END; new_url:=CASE WHEN NEW.url_slug='' THEN NEW.path ELSE base||NEW.url_slug END; DELETE FROM public.seo_redirects WHERE source_path=new_url; INSERT INTO public.seo_redirects(source_path,target_path) VALUES(old_url,new_url) ON CONFLICT(source_path) DO UPDATE SET target_path=excluded.target_path,active=true; UPDATE public.seo_redirects SET target_path=new_url WHERE target_path=old_url AND source_path<>old_url; END IF; RETURN NEW; END $$;
CREATE TRIGGER seo_page_update BEFORE UPDATE ON public.seo_pages FOR EACH ROW EXECUTE FUNCTION public.seo_page_changed();
ALTER TABLE public.posts ADD COLUMN publish_at timestamptz, ADD COLUMN image_alt_ar text NOT NULL DEFAULT '', ADD COLUMN image_alt_en text NOT NULL DEFAULT '';
UPDATE public.posts SET publish_at=created_at;
CREATE OR REPLACE FUNCTION public.is_published_media(_url text) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT _url LIKE '/api/public/media/%' AND (EXISTS(SELECT 1 FROM public.products WHERE active AND image_url=_url) OR EXISTS(SELECT 1 FROM public.slides WHERE active AND (image_url=_url OR link=_url)) OR EXISTS(SELECT 1 FROM public.posts WHERE published AND image_url=_url) OR EXISTS(SELECT 1 FROM public.services WHERE image_url=_url) OR EXISTS(SELECT 1 FROM public.sections WHERE image_url=_url) OR EXISTS(SELECT 1 FROM public.site_settings WHERE id=1 AND (logo_url=_url OR app_link=_url OR login_logo_url=_url OR login_background_url=_url OR (popup_enabled AND popup_link=_url) OR (serial_bg_enabled AND serial_bg_image=_url))) OR EXISTS(SELECT 1 FROM public.seo_pages WHERE image_url=_url AND robots='index') OR EXISTS(SELECT 1 FROM public.seo_images WHERE optimized_url=_url)); $$;